<?php
require_once __DIR__.'/config.php';
$pdo=db(); $productId=(int)($_POST['product_id']??0); $name=trim($_POST['customer_name']??''); $content=trim($_POST['content']??''); $rating=max(1,min(5,(int)($_POST['rating']??5))); $returnUrl=$_SERVER['HTTP_REFERER']??'index.php';
if(!$pdo||!$productId||$name===''||$content===''){header('Location: '.$returnUrl);exit;}
try{$pdo->beginTransaction();$q=$pdo->prepare('INSERT INTO product_reviews(product_id,customer_name,rating,content) VALUES(?,?,?,?)');$q->execute([$productId,$name,$rating,$content]);$reviewId=$pdo->lastInsertId();$dir=__DIR__.'/uploads/reviews';if(!is_dir($dir))mkdir($dir,0775,true);$save=$pdo->prepare('INSERT INTO product_review_images(review_id,image_url,sort_order) VALUES(?,?,?)');foreach($_FILES['images']['tmp_name']??[] as $i=>$tmp){if(!is_uploaded_file($tmp))continue;$mime=mime_content_type($tmp);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))continue;$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime];$file=bin2hex(random_bytes(16)).'.'.$ext;if(move_uploaded_file($tmp,$dir.'/'.$file))$save->execute([$reviewId,'/uploads/reviews/'.$file,$i]);}$pdo->commit();$returnUrl=preg_replace('/#.*$/','',$returnUrl).(str_contains($returnUrl,'?')?'&':'?').'review=success#reviews';}catch(Throwable $e){if($pdo&&$pdo->inTransaction())$pdo->rollBack();}header('Location: '.$returnUrl);
